payload.css:
:host { display: block; color: #f4f0e4; font: 600 12px/1.35 ui-sans-serif, system-ui, sans-serif; letter-spacing: .055em; user-select: none; }
.aetherfall-hud { --safe-x: clamp(18px, 2.5vw, 38px); --safe-y: clamp(16px, 2.3vw, 30px); --gold: #ecd991; --cyan: #9bcac5; position: absolute; inset: 0; overflow: hidden; pointer-events: none; text-shadow: 0 2px 10px rgb(0 7 10 / 82%); }
.eyebrow { display: block; color: var(--cyan); font-size: 8px; font-weight: 750; letter-spacing: .19em; }
.identity, .quest, .compass, .interaction, .completion, .controls { box-sizing: border-box; position: absolute; }
.identity { top: var(--safe-y); left: var(--safe-x); padding-left: 10px; border-left: 1px solid rgb(236 217 145 / 58%); }
.identity strong { display: block; margin-top: 2px; color: #fff9e7; font-size: clamp(15px, 1.35vw, 19px); font-weight: 720; letter-spacing: .145em; }
.quest { top: calc(var(--safe-y) + 45px); left: var(--safe-x); width: min(304px, calc(100% - var(--safe-x) * 2)); padding: 9px 12px 10px 13px; border-left: 2px solid rgb(236 217 145 / 72%); background: linear-gradient(90deg, rgb(4 18 23 / 82%) 0%, rgb(7 25 29 / 57%) 72%, transparent 100%); backdrop-filter: blur(3px); }
.quest-meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.quest strong { display: block; margin: 4px 0 8px; color: #fff7dc; font-size: 11px; font-weight: 650; letter-spacing: .025em; }
.progress-track { height: 2px; overflow: hidden; background: rgb(210 230 221 / 18%); }
.progress-track > span { display: block; width: 0; height: 100%; background: linear-gradient(90deg, #82bbb7, var(--gold)); box-shadow: 0 0 7px rgb(236 217 145 / 58%); transition: width 220ms ease-out; }
[data-ui-slot="progress-label"] { flex: none; color: #b8d4cf; font-size: 8px; letter-spacing: .12em; }
.compass { top: var(--safe-y); left: 50%; display: flex; align-items: center; gap: 8px; max-width: min(320px, calc(100% - 430px)); color: #d7e5df; transform: translateX(-50%); }
.compass::before, .compass::after { width: clamp(18px, 3vw, 42px); height: 1px; background: linear-gradient(90deg, transparent, rgb(155 202 197 / 55%)); content: ''; }
.compass::after { background: linear-gradient(90deg, rgb(155 202 197 / 55%), transparent); }
.compass i { width: 4px; height: 4px; border: 1px solid rgb(236 217 145 / 80%); transform: rotate(45deg); }
[data-ui-slot="heading"] { color: var(--gold); font-size: 11px; font-weight: 800; letter-spacing: .12em; }
[data-ui-slot="landmark"] { overflow: hidden; color: #bed2cd; font-size: 8px; letter-spacing: .13em; text-overflow: ellipsis; white-space: nowrap; }
.interaction, .completion { bottom: calc(var(--safe-y) + 27px); left: 50%; display: flex; align-items: center; gap: 10px; max-width: min(390px, calc(100% - var(--safe-x) * 2)); padding: 6px 11px 6px 7px; border: 1px solid rgb(155 202 197 / 36%); border-radius: 2px; background: linear-gradient(90deg, rgb(4 18 23 / 80%), rgb(7 27 30 / 70%)); box-shadow: inset 0 1px rgb(255 255 255 / 4%), 0 6px 22px rgb(0 8 11 / 20%); color: #dcece5; transform: translateX(-50%); backdrop-filter: blur(4px); }
.interaction::after { position: absolute; right: -1px; bottom: -1px; width: 14px; height: 1px; background: var(--cyan); content: ''; opacity: .62; }
kbd { display: grid; width: 22px; height: 22px; flex: none; place-items: center; border: 1px solid rgb(236 217 145 / 64%); border-radius: 2px; background: rgb(236 217 145 / 9%); box-shadow: inset 0 0 0 1px rgb(0 0 0 / 22%); color: var(--gold); font: 800 10px/1 ui-sans-serif, system-ui, sans-serif; }
[data-ui-slot="interaction-copy"] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.interaction[data-state="beacon-ready"] { border-color: rgb(236 217 145 / 64%); color: #fff2bd; animation: beacon-breathe 2.8s ease-in-out infinite; }
.completion { bottom: calc(var(--safe-y) + 48px); display: block; padding: 8px 18px; border-color: rgb(236 217 145 / 65%); background: linear-gradient(90deg, rgb(21 24 18 / 82%), rgb(41 37 21 / 72%)); color: #fff0b0; font-size: 13px; letter-spacing: .1em; }
.controls { bottom: var(--safe-y); left: var(--safe-x); max-width: calc(100% - var(--safe-x) * 2); overflow: hidden; color: rgb(199 221 215 / 78%); font-size: 8px; letter-spacing: .11em; text-overflow: ellipsis; white-space: nowrap; }
.aetherfall-hud[data-phase="complete"] .quest { border-left-color: var(--gold); }
.aetherfall-hud[data-phase="complete"] .progress-track > span { background: var(--gold); }
@keyframes beacon-breathe { 0%, 100% { box-shadow: inset 0 1px rgb(255 255 255 / 4%), 0 6px 22px rgb(0 8 11 / 20%); } 50% { box-shadow: inset 0 1px rgb(255 255 255 / 7%), 0 0 18px rgb(236 217 145 / 18%); } }
@media (max-width: 700px) { .aetherfall-hud { --safe-x: 14px; --safe-y: 13px; } .identity .eyebrow { display: none; } .identity { padding-left: 8px; } .quest { top: 48px; width: min(280px, calc(100% - 28px)); } .compass { right: 14px; left: auto; max-width: calc(100% - 180px); transform: none; } .compass::before { display: none; } .controls { max-width: calc(100% - 28px); } }
@media (max-width: 430px) { .identity strong { font-size: 14px; } .quest { top: 43px; padding-block: 7px 8px; } .quest strong { margin-block: 3px 6px; font-size: 10px; } .compass { max-width: calc(100% - 150px); } .compass::after, .compass i { display: none; } .interaction { bottom: 39px; max-width: calc(100% - 28px); font-size: 10px; } .controls { font-size: 7px; letter-spacing: .045em; } }
@media (max-height: 520px) { .quest { top: 42px; } .interaction { bottom: 34px; } .controls { bottom: 10px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; } }
